CREATE DATABASE IF NOT EXISTS fairstream; USE fairstream;
CREATE TABLE users (user_id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('listener','artist') NOT NULL DEFAULT 'listener', wallet_address VARCHAR(42), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE artists (artist_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT UNIQUE NOT NULL, stage_name VARCHAR(100) NOT NULL, FOREIGN KEY (user_id) REFERENCES users(user_id));
CREATE TABLE tracks (track_id INT AUTO_INCREMENT PRIMARY KEY, artist_id INT NOT NULL, title VARCHAR(150) NOT NULL, description TEXT, cover_url VARCHAR(500), ipfs_cid VARCHAR(255) NOT NULL, license VARCHAR(50) DEFAULT 'CC BY', FOREIGN KEY (artist_id) REFERENCES artists(artist_id));
CREATE TABLE plans (plan_id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) NOT NULL, price DECIMAL(10,2) NOT NULL, has_ads BOOLEAN NOT NULL);
CREATE TABLE subscriptions (subscription_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, plan_id INT NOT NULL, start_date DATE NOT NULL, status ENUM('active','settled') DEFAULT 'active', pool_amount DECIMAL(10,2) NOT NULL, FOREIGN KEY (user_id) REFERENCES users(user_id), FOREIGN KEY (plan_id) REFERENCES plans(plan_id));
CREATE TABLE stream_logs (log_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, track_id INT NOT NULL, seconds_played INT NOT NULL, played_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(user_id), FOREIGN KEY (track_id) REFERENCES tracks(track_id));
CREATE TABLE royalty_settlements (settlement_id INT AUTO_INCREMENT PRIMARY KEY, artist_id INT NOT NULL, period CHAR(7) NOT NULL, amount_kes DECIMAL(10,2) NOT NULL, status ENUM('pending','paid') DEFAULT 'pending', FOREIGN KEY (artist_id) REFERENCES artists(artist_id));
CREATE TABLE payouts (payout_id INT AUTO_INCREMENT PRIMARY KEY, settlement_id INT UNIQUE NOT NULL, tx_hash VARCHAR(100) NOT NULL, paid_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (settlement_id) REFERENCES royalty_settlements(settlement_id));
INSERT INTO plans (name, price, has_ads) VALUES ('Free', 0, TRUE), ('Premium', 300, FALSE);
CREATE TABLE track_splits (split_id INT AUTO_INCREMENT PRIMARY KEY, track_id INT NOT NULL, collaborator_name VARCHAR(100) NOT NULL, role VARCHAR(50) NOT NULL, wallet_address VARCHAR(42), percent DECIMAL(5,2) NOT NULL, FOREIGN KEY (track_id) REFERENCES tracks(track_id));
